jsb-if.script.js:
function packingLabel(weightKg) {
  let label = '普通包装';
  if (weightKg >= 10) {
    label = '加固包装';
  }
  return label;
}

jsb-accumulator.script.js:
function screeningCapacity(rows) {
  let total = 0;
  let seats = 4;
  for (let row = 0; row < rows; row += 1) {
    total += seats;
    seats += 2;
  }
  return total;
}
